function down(k){if(!keys.has(k))pressed.add(k);keys.add(k);if(k==='KeyM'){map=!map;pressed.delete(k);}if(k==='KeyP'||k==='Escape'){paused=!paused;pressed.delete(k);}}
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!e.repeat)down(e.code);});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();pressed.clear();if(running)paused=true;});
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);down(b.dataset.key);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(b.dataset.key));}
function imageReady(im,src){return new Promise((resolve,reject)=>{let done=false;const timer=setTimeout(()=>finish(new Error('Tempo de carregamento excedido')),20000);function finish(err){if(done)return;done=true;clearTimeout(timer);im.onload=im.onerror=null;err?reject(err):resolve();}im.onload=()=>finish();im.onerror=()=>finish(new Error('Imagem indisponível'));if(im.complete&&im.naturalWidth)finish();else if(src)im.src=src;});}
async function loadScene(){const epoch=++loadEpoch,sceneId=rooms[state.room].scene;loading=true;loadError='';loadProgress=0;$('#play').disabled=true;$('#retry').hidden=true;try{arts[sceneId].fetchPriority='high';await Promise.all([imageReady(hero,hero.src).then(()=>loadProgress++),imageReady(arts[sceneId],L.scenes[sceneId].src).then(()=>{loaded.add('art'+sceneId);loadProgress++;})]);if(epoch!==loadEpoch)return;loading=false;if(!running)$('#hud').textContent='PRONTO · v0.9';$('#play').disabled=false;$('#play').textContent=running?'Continuar':'Jogar agora';if(!orb.src)imageReady(orb,ORB_SRC).catch(()=>{});for(let i=0;i<arts.length;i++)if(i!==sceneId&&!loaded.has('art'+i))imageReady(arts[i],L.scenes[i].src).then(()=>loaded.add('art'+i)).catch(()=>{});}catch(e){if(epoch!==loadEpoch)return;loading=false;$('#hud').textContent='FALHA NO CARREGAMENTO';loadError='Não foi possível carregar a cena. Toque em Tentar novamente.';$('#retry').hidden=false;}}
// Drones are optional for readiness; render() has a vector fallback.
$('#retry').onclick=()=>loadScene();loadScene();
$('#play').onclick=()=>{if(loading||loadError)return;running=true;paused=false;$('#intro').hidden=true;$('#play').textContent='Continuar';};$('#map').onclick=()=>map=!map;$('#pause').onclick=()=>paused=!paused;$('#restart').onclick=()=>{if(!confirm('Apagar o progresso deste protótipo e recomeçar?'))return;state={room:0,owned:[],visited:[0],open:[],done:false};enter(0);running=true;paused=false;map=false;};$('#full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.querySelector('main').requestFullscreen?.().catch(()=>say('Tela cheia indisponível neste navegador.'));};
if(new URLSearchParams(location.search).has('test'))window.CITY_TEST={get p(){return p},get state(){return state},get enemies(){return enemies},rooms,doors,rewards,point,enter,step,render,interact,has,keys,press:down,start(){running=true;paused=false},get terrain(){return terrain},get lift(){return lift},get paused(){return paused},camera,get hitstop(){return hitstop},get effects(){return fx},get loading(){return loading},get loadError(){return loadError},loaded};
